// ---------------- lookup helpers ----------------

#[allow(dead_code)]
pub(crate) fn lookup_decomp(cp: u32) -> Option<(&'static [u32], bool)> {
    let idx = DECOMP_TABLE.binary_search_by_key(&cp, |e| e.source).ok()?;
    let e = DECOMP_TABLE[idx];
    let off = e.pool_off as usize;
    let len = e.len as usize;
    Some((&DECOMP_POOL[off..off + len], e.is_compat != 0))
}

#[allow(dead_code)]
pub(crate) fn lookup_ccc(cp: u32) -> u8 {
    match CCC_TABLE.binary_search_by_key(&cp, |&(k, _)| k) {
        Ok(i) => CCC_TABLE[i].1,
        Err(_) => 0,
    }
}

#[allow(dead_code)]
pub(crate) fn lookup_composite(a: u32, b: u32) -> Option<u32> {
    let idx = COMPOSE_TABLE
        .binary_search_by_key(&(a, b), |&(k, _)| k)
        .ok()?;
    Some(COMPOSE_TABLE[idx].1)
}

/// Returns 0 (Yes), 1 (No), or 2 (Maybe). cps beyond bitmap default to Yes.
#[allow(dead_code)]
#[inline]
pub(crate) fn lookup_qc(bitmap: &[u8], cp: u32) -> u8 {
    let byte_idx = (cp / 4) as usize;
    if byte_idx >= bitmap.len() {
        return 0;
    }
    let bit_off = (cp % 4) * 2;
    (bitmap[byte_idx] >> bit_off) & 0b11
}

/// Largest cp with a non-Y QC entry across all 4 bitmaps. cps > 0X2FA1D short-circuit to Y.
#[allow(dead_code)]
pub(crate) const QC_MAX_CP: u32 = 0x2FA1D;
